repo.readings.py:
"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('east', 53), ('south', 49), ('east', 32), ('north', 39), ('south', 10)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)

repo.positions.py:
"""Position windows over readings."""


def level_between(readings, low, high):
    """Return the level of the readings at positions low to high, both included. Positions start at 1."""
    return [x.level for x in readings[low - 1:high - 1]]


def first_levels(readings, n):
    """Return the level of the first n readings."""
    return level_between(readings, 1, n)


def largest_level(readings):
    """Return the largest level, or None when there are no readings."""
    values = [x.level for x in readings]
    return max(values) if values else None


def describe_reading(reading):
    """Return a one-line description of a reading."""
    return "%s: %s" % (reading.sensor, reading.level)

